describe('Notification Visual Distinction', () => {
  beforeEach(() => {
    cy.visit('/notifications');
    cy.intercept('GET', '/api/notifications', {
      statusCode: 200,
      body: {
        notifications: [
          {
            id: '1',
            message: 'You have a new message',
            read: false,
            timestamp: '2024-01-15T10:30:00Z'
          },
          {
            id: '2',
            message: 'Your order has shipped',
            read: true,
            timestamp: '2024-01-14T15:20:00Z'
          },
          {
            id: '3',
            message: 'New comment on your post',
            read: false,
            timestamp: '2024-01-13T09:15:00Z'
          }
        ]
      }
    }).as('getNotifications');
    cy.wait('@getNotifications');
  });

  it('should display unread notifications with distinct visual styling', () => {
    // Verify unread notifications have distinct background color
    cy.get('[data-testid="notification-item"][data-read="false"]')
      .should('have.length', 2)
      .each(($notification) => {
        cy.wrap($notification)
          .should('have.css', 'background-color')
          .and('not.equal', 'rgb(255, 255, 255)');
      });

    // Verify unread notifications have bold text
    cy.get('[data-testid="notification-item"][data-read="false"] [data-testid="notification-message"]')
      .should('have.css', 'font-weight')
      .and('match', /^(700|bold)$/);

    // Verify unread notifications have a visual indicator badge
    cy.get('[data-testid="notification-item"][data-read="false"] [data-testid="unread-badge"]')
      .should('be.visible')
      .and('have.length', 2);
  });

  it('should display read notifications with standard styling', () => {
    // Verify read notifications have standard background
    cy.get('[data-testid="notification-item"][data-read="true"]')
      .should('have.length', 1)
      .should('have.css', 'background-color', 'rgb(255, 255, 255)');

    // Verify read notifications have normal font weight
    cy.get('[data-testid="notification-item"][data-read="true"] [data-testid="notification-message"]')
      .should('have.css', 'font-weight')
      .and('match', /^(400|normal)$/);

    // Verify read notifications do not have unread badge
    cy.get('[data-testid="notification-item"][data-read="true"] [data-testid="unread-badge"]')
      .should('not.exist');
  });

  it('should update visual styling when notification is marked as read', () => {
    // Get first unread notification
    cy.get('[data-testid="notification-item"][data-read="false"]').first().as('unreadNotification');

    // Verify initial unread state
    cy.get('@unreadNotification')
      .should('have.css', 'background-color')
      .and('not.equal', 'rgb(255, 255, 255)');

    // Click to mark as read
    cy.get('@unreadNotification').click();
    cy.intercept('PATCH', '/api/notifications/1', {
      statusCode: 200,
      body: { id: '1', read: true }
    }).as('markAsRead');
    cy.wait('@markAsRead');

    // Verify styling changed to read state
    cy.get('[data-testid="notification-item"][data-read="true"]')
      .first()
      .should('have.css', 'background-color', 'rgb(255, 255, 255)');

    cy.get('[data-testid="notification-item"][data-read="true"] [data-testid="unread-badge"]')
      .should('not.exist');
  });

  it('should maintain visual distinction with multiple unread notifications', () => {
    // Verify all unread notifications are visually consistent
    cy.get('[data-testid="notification-item"][data-read="false"]')
      .should('have.length', 2)
      .each(($notification, index) => {
        cy.wrap($notification)
          .should('have.attr', 'data-read', 'false');

        cy.wrap($notification)
          .find('[data-testid="unread-badge"]')
          .should('be.visible');

        cy.wrap($notification)
          .should('have.css', 'border-left')
          .and('include', 'rgb');
      });

    // Verify unread count is visible
    cy.get('[data-testid="unread-count"]')
      .should('contain', '2');
  });

  it('should handle empty notification state gracefully', () => {
    cy.intercept('GET', '/api/notifications', {
      statusCode: 200,
      body: { notifications: [] }
    }).as('emptyNotifications');

    cy.visit('/notifications');
    cy.wait('@emptyNotifications');

    cy.get('[data-testid="notification-item"]')
      .should('not.exist');

    cy.get('[data-testid="empty-state"]')
      .should('be.visible')
      .and('contain', 'No notifications');
  });
});
